        char ch = board[r][c];
        Object childObj = node.get(ch);
        if (childObj == null) return;             // no word continues down this path, prune immediately
        @SuppressWarnings("unchecked")
        Map<Character, Object> next = (Map<Character, Object>) childObj;
        if (next.containsKey('#')) found.add((String) next.get('#'));
        board[r][c] = '#';
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length && board[nr][nc] != '#') {
                dfs(board, nr, nc, next, found);
            }
        }
        board[r][c] = ch;
    }
    // Build the trie from all words first, storing the complete word under key '#' at its final node.
}

