struct TrieNode {
    TrieNode* children[26] = {};
    string word = "";
};

void dfs(vector<vector<char>>& board, int r, int c, TrieNode* node, set<string>& found) {
    char ch = board[r][c];
    if (!node->children[ch - 'a']) return;        // no word continues down this path, prune immediately
    TrieNode* next = node->children[ch - 'a'];
    if (!next->word.empty()) found.insert(next->word);
    board[r][c] = '#';
    int dr[] = {1,-1,0,0}, dc[] = {0,0,1,-1};
    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i], nc = c + dc[i];
        if (nr >= 0 && nr < (int)board.size() && nc >= 0 && nc < (int)board[0].size() && board[nr][nc] != '#') {
            dfs(board, nr, nc, next, found);
        }
    }
    board[r][c] = ch;
}
